<?php require_once __DIR__.'/config.php'; if(current_user()){header('Location:index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??null)){$error='Security token expired. Refresh and try again.';}else{[$ok,$msg]=$chat->register($_POST['name']??'',$_POST['phone']??'',$_POST['password']??'');if($ok){$_SESSION['user_id']=(int)$msg;session_regenerate_id(true);header('Location:index.php');exit;} $error=$msg;}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account — WhatsApp Clone</title><link rel="stylesheet" href="auth.css"></head><body><main class="auth-page"><section class="auth-card"><div class="brand"><div class="brand-mark">☏</div><div><h1>WhatsApp Clone</h1><p>Create your messaging account</p></div></div><h2>Create account</h2><p class="sub">Your users can chat with other accounts on this app.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Full name</label><input name="name" autocomplete="name" required placeholder="Your name"></div><div class="field"><label>Phone number</label><input name="phone" type="tel" autocomplete="tel" required placeholder="08012345678"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="new-password" minlength="6" required placeholder="At least 6 characters"></div><button class="primary">Create account</button></form><div class="auth-link">Already have an account? <a href="login.php">Log in</a></div></section></main></body></html>
